PRAGMA foreign_keys= ON;
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,name TEXT NOT NULL,objective TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,department_id TEXT NOT NULL REFERENCES departments(id),name TEXT NOT NULL,role TEXT NOT NULL,autonomy_level TEXT NOT NULL DEFAULT 'bounded',status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS organisational_memory(id TEXT PRIMARY KEY,department_id TEXT REFERENCES departments(id),owner_agent_id TEXT REFERENCES agents(id),memory_type TEXT NOT NULL,content_json TEXT NOT NULL,sensitivity TEXT NOT NULL DEFAULT 'internal',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE INDEX IF NOT EXISTS idx_memory_department_created ON organisational_memory(department_id,created_at DESC);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,department_id TEXT NOT NULL REFERENCES departments(id),assigned_agent_id TEXT REFERENCES agents(id),title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',priority INTEGER NOT NULL DEFAULT 3,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_instruments(id TEXT PRIMARY KEY,exchange TEXT NOT NULL,product_type TEXT NOT NULL,symbol TEXT NOT NULL,base_coin TEXT,quote_coin TEXT,tick_size TEXT,quantity_step TEXT,min_size TEXT,status TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(exchange,product_type,symbol));
CREATE TABLE IF NOT EXISTS signal_events(id TEXT PRIMARY KEY,instrument_id TEXT,direction TEXT NOT NULL,decision TEXT NOT NULL,score REAL NOT NULL,evidence_json TEXT NOT NULL,strategy_versions_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS risk_assessments(id TEXT PRIMARY KEY,signal_id TEXT REFERENCES signal_events(id),approved INTEGER NOT NULL,reasons_json TEXT NOT NULL,metrics_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,client_oid TEXT NOT NULL UNIQUE,exchange_order_id TEXT,instrument_id TEXT,product_type TEXT NOT NULL,side TEXT NOT NULL,order_type TEXT NOT NULL,quantity TEXT NOT NULL,price TEXT,status TEXT NOT NULL,request_json TEXT NOT NULL,response_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_fills(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),exchange_fill_id TEXT UNIQUE,quantity TEXT NOT NULL,price TEXT NOT NULL,fee TEXT,fee_coin TEXT,filled_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS positions(id TEXT PRIMARY KEY,instrument_id TEXT NOT NULL,product_type TEXT NOT NULL,side TEXT NOT NULL,quantity TEXT NOT NULL,entry_price TEXT,leverage TEXT,margin_mode TEXT,stop_loss TEXT,take_profit_json TEXT NOT NULL DEFAULT '[]',protection_status TEXT NOT NULL DEFAULT 'unknown',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);